package place.icomb.archiver.config;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.nimbusds.jose.jwk.source.JWKSource;
import com.nimbusds.jose.proc.SecurityContext;
import org.junit.jupiter.api.Test;

class McpJwkConfigTest {

  // A throwaway 2048-bit RSA key, base64-encoded PEM, used only in this test.
  // Generate your own with: openssl genrsa 2048 | base64 | tr -d '\n'
  private static final String TEST_KEY_B64 =
      "";

  @Test
  void buildsAnRsaJwkFromTheConfiguredBase64Pem() {
    McpJwkConfig config = new McpJwkConfig(TEST_KEY_B64);

    JWKSource<SecurityContext> source = config.jwkSource();

    assertThat(source).isNotNull();
  }

  @Test
  void blankSigningKeyFailsFastAtStartupRatherThanSilentlyGeneratingAnEphemeralKey() {
    assertThatThrownBy(() -> new McpJwkConfig(""))
        .isInstanceOf(IllegalStateException.class)
        .hasMessageContaining("archiver.mcp.oauth.signing-key-b64");
  }
}
